# Fix Next.js 16 - middleware to proxy + edge-safe auth

$ErrorActionPreference = "Stop"

if (-not (Test-Path "package.json")) {
    Write-Host "ERRO: corre dentro de xenco-surfshop" -ForegroundColor Red
    exit 1
}

Write-Host ""
Write-Host "Aplicando fix Next.js 16..." -ForegroundColor Cyan
Write-Host ""

# Apagar middleware.ts antigo (foi substituido por proxy.ts)
if (Test-Path "src/middleware.ts") {
    Remove-Item "src/middleware.ts" -Force
    Write-Host "  OK Apagado src/middleware.ts" -ForegroundColor Yellow
}

# src/auth.config.ts
$b64 = ""
$path = "$PWD\src\auth.config.ts"
$bytes = [System.Convert]::FromBase64String($b64)
$utf8 = [System.Text.UTF8Encoding]::new($false)
$text = $utf8.GetString($bytes)
[System.IO.File]::WriteAllText($path, $text, $utf8)
Write-Host "  OK src/auth.config.ts" -ForegroundColor Green

# src/auth.ts
$b64 = ""
$path = "$PWD\src\auth.ts"
$bytes = [System.Convert]::FromBase64String($b64)
$utf8 = [System.Text.UTF8Encoding]::new($false)
$text = $utf8.GetString($bytes)
[System.IO.File]::WriteAllText($path, $text, $utf8)
Write-Host "  OK src/auth.ts" -ForegroundColor Green

# src/proxy.ts
$b64 = ""
$path = "$PWD\src\proxy.ts"
$bytes = [System.Convert]::FromBase64String($b64)
$utf8 = [System.Text.UTF8Encoding]::new($false)
$text = $utf8.GetString($bytes)
[System.IO.File]::WriteAllText($path, $text, $utf8)
Write-Host "  OK src/proxy.ts" -ForegroundColor Green

Write-Host ""
Write-Host "Fix aplicado. Corre: npm run dev" -ForegroundColor Cyan